sqlite.source:
export function sqliteIdentifierValid(name: []u8): bool {
    if len(name) == 0 as usize { return false }
    let i: usize = 0 as usize
    while i < len(name) {
        let c: u8 = name[i]
        if c == 95 as u8 { i = i + 1 as usize }
        else if (c >= 65 as u8 && c <= 90 as u8) || (c >= 97 as u8 && c <= 122 as u8) { i = i + 1 as usize }
        else if i > 0 as usize && c >= 48 as u8 && c <= 57 as u8 { i = i + 1 as usize }
        else { return false }
    }
    return true
}
export function sqliteRetryable(code: int): bool { return sqliteBusy(code) || code == 10 }

sqlite.test:
let good: [u8; 3] = [97 as u8,95 as u8,49 as u8]
let bad: [u8; 2] = [49 as u8,97 as u8]
if !sqliteIdentifierValid(slice(good)) || sqliteIdentifierValid(slice(bad)) { return 1 }
if !sqliteRetryable(5) || sqliteRetryable(19) { return 2 }

postgres.source:
export function postgresIdentifierValid(name: []u8): bool {
    if len(name) == 0 as usize || len(name) > 63 as usize { return false }
    let i: usize = 0 as usize
    while i < len(name) {
        let c: u8 = name[i]
        let letter: bool = (c >= 65 as u8 && c <= 90 as u8) || (c >= 97 as u8 && c <= 122 as u8) || c == 95 as u8
        let number: bool = i > 0 as usize && c >= 48 as u8 && c <= 57 as u8
        if !letter && !number { return false }
        i = i + 1 as usize
    }
    return true
}
export function postgresPayloadLengthValid(frameBytes: usize): bool { return frameBytes >= 5 as usize && frameBytes <= 16777217 as usize }

postgres.test:
let valid: [u8; 2] = [97 as u8,49 as u8]
let bad: [u8; 2] = [49 as u8,97 as u8]
if !postgresIdentifierValid(slice(valid)) || postgresIdentifierValid(slice(bad)) { return 1 }
if postgresPayloadLengthValid(4 as usize) || !postgresPayloadLengthValid(5 as usize) { return 2 }

tls.source:
export function tlsRecordHeaderValid(header: []u8): bool {
    if len(header) != 5 as usize { return false }
    if !tlsContentTypeValid(header[0]) || !tlsLegacyVersionValid(header[1],header[2]) { return false }
    let length: usize = header[3] as usize * 256 as usize + header[4] as usize
    return length <= 18432 as usize
}

